import{_ as a}from"./chunks/image2.dcWZr_SF.js";import{_ as i,o as n,c as s,ah as l}from"./chunks/framework.DE1cwP7O.js";const e="/projects/DaDablock-AI/en/starter-kit/assets/image.DirOej9m.png",c="/projects/DaDablock-AI/en/starter-kit/assets/image3.iTwzmnhz.png",h="/projects/DaDablock-AI/en/starter-kit/assets/image4.DRkInU8K.png",g="/projects/DaDablock-AI/en/starter-kit/assets/image1.gAgmRPNY.png",d="/projects/DaDablock-AI/en/starter-kit/assets/image2.B8zc0Jpr.png",p="/projects/DaDablock-AI/en/starter-kit/assets/image3.Bfu-hF-7.png",m="/projects/DaDablock-AI/en/starter-kit/assets/image4.Dpw6DOJM.png",u="/projects/DaDablock-AI/en/starter-kit/assets/image5.B8U9f3P-.png",w="/projects/DaDablock-AI/en/starter-kit/assets/image6.B3MpXkrF.png",b="/projects/DaDablock-AI/en/starter-kit/assets/image7.Co4TRYvD.png",_="/projects/DaDablock-AI/en/starter-kit/assets/image1.CjIZMJTS.png",o="/projects/DaDablock-AI/en/starter-kit/assets/image2.CW68a9kI.png",k="/projects/DaDablock-AI/en/starter-kit/assets/image3.DJK6UrXx.png",f="/projects/DaDablock-AI/en/starter-kit/assets/image4.CslFUZqF.png",y="/projects/DaDablock-AI/en/starter-kit/assets/image5.DL3pFkf4.png",D="/projects/DaDablock-AI/en/starter-kit/assets/image5.B_i69b6r.png",x="/projects/DaDablock-AI/en/starter-kit/assets/image7.BMzRBVLm.png",P="/projects/DaDablock-AI/en/starter-kit/assets/image8.DcdwK21P.png",C="/projects/DaDablock-AI/en/starter-kit/assets/image9.BJ7LQ1S2.png",r="/projects/DaDablock-AI/en/starter-kit/assets/image6.CoUGIQ2z.gif",S="/projects/DaDablock-AI/en/starter-kit/assets/image1.C7qlYojH.png",q="/projects/DaDablock-AI/en/starter-kit/assets/image3.DO9dr6KW.png",M=JSON.parse('{"title":"2. Quick Start Guide","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2_Quick_Start.md","filePath":"docs/2_Quick_Start.md"}'),v={name:"docs/2_Quick_Start.md"};function j(z,t,I,A,O,B){return n(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="_2-quick-start-guide" tabindex="-1">2. Quick Start Guide <a class="header-anchor" href="#_2-quick-start-guide" aria-label="Permalink to &quot;2. Quick Start Guide&quot;">​</a></h1><h2 id="_2-1-hardware-preparation" tabindex="-1">2.1 Hardware Preparation <a class="header-anchor" href="#_2-1-hardware-preparation" aria-label="Permalink to &quot;2.1 Hardware Preparation&quot;">​</a></h2><h3 id="_2-1-1-powering-on" tabindex="-1">2.1.1 Powering On <a class="header-anchor" href="#_2-1-1-powering-on" aria-label="Permalink to &quot;2.1.1 Powering On&quot;">​</a></h3><ol><li>Make sure the controller power switch is set to <strong>OFF</strong>. Install the battery in the battery compartment of the controller.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Make sure the positive and negative terminals are not reversed.</strong></p></div><img loading="lazy" height="2001" width="2000" src="'+e+'" class="inline-icon" style="width:400px;"><ol start="2"><li>Turn on the power switch. The power indicator LED on the controller lights red, indicating a successful power-on.</li></ol><img loading="lazy" height="656" width="486" src="'+a+'" class="common_img" style="width:200px;"><h3 id="_2-1-2-charging" tabindex="-1">2.1.2 Charging <a class="header-anchor" href="#_2-1-2-charging" aria-label="Permalink to &quot;2.1.2 Charging&quot;">​</a></h3><ol><li>Make sure the controller power switch is set to <strong>OFF</strong>. Install the battery in the battery compartment of the controller.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ul><li><p><strong>Make sure the positive and negative terminals are not reversed.</strong></p></li><li><p><strong>When powering on for the first time, follow the steps in &quot;2.1.2 Charging&quot; to charge at the charging port for about 5 seconds to activate the built-in battery protection chip. Once activated, reactivation is not required unless the battery is unplugged.</strong></p></li></ul></div><img loading="lazy" height="2001" width="2000" src="'+e+'" class="inline-icon" style="width:400px;"><ol start="2"><li>Connect a USB data cable to the charging port on the controller, and connect the other end to a charger.</li></ol><img loading="lazy" height="1146" width="860" src="'+c+'" class="inline-icon" style="width:400px;"><ol start="3"><li>While charging, the controller LED lights up blue. When charging is complete, the LED turns off. Disconnect the power cable promptly after charging to avoid overcharging.</li></ol><img loading="lazy" height="2961" width="3214" src="'+h+'" class="inline-icon" style="width:400px;"><h2 id="_2-2-wondercode-installation" tabindex="-1">2.2 WonderCode Installation <a class="header-anchor" href="#_2-2-wondercode-installation" aria-label="Permalink to &quot;2.2 WonderCode Installation&quot;">​</a></h2><ol><li>Open <strong><a href="https://www.hiwonder.net/pc-programming-software" target="_blank" rel="noreferrer">WonderCode setup.exe</a></strong>.</li></ol><img loading="lazy" height="105" width="75" src="'+g+'" class="inline-icon" style="width:80px;"><ol start="2"><li>Select the installation language, then click <strong>OK</strong>.</li></ol><img loading="lazy" height="162" width="349" src="'+d+'" class="inline-icon" style="width:350px;"><ol start="3"><li>Select the installation location, then click <strong>Next</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+p+'" class="inline-icon" style="width:450px;"><ol start="4"><li>Click <strong>Next</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+m+'" class="inline-icon" style="width:450px;"><ol start="5"><li>Click <strong>Install</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+u+'" class="inline-icon" style="width:450px;"><img loading="lazy" height="415" width="582" src="'+w+'" class="inline-icon" style="width:450px;"><ol start="6"><li>After the installation is complete, click <strong>Finish</strong>.</li></ol><img loading="lazy" height="415" width="582" src="'+b+'" class="inline-icon" style="width:450px;"><h2 id="_2-3-starter-project-1-blinking-onboard-rgb-lights" tabindex="-1">2.3 Starter Project 1: Blinking Onboard RGB Lights <a class="header-anchor" href="#_2-3-starter-project-1-blinking-onboard-rgb-lights" aria-label="Permalink to &quot;2.3 Starter Project 1: Blinking Onboard RGB Lights&quot;">​</a></h2><h3 id="_2-3-1-programming-steps" tabindex="-1">2.3.1 Programming Steps <a class="header-anchor" href="#_2-3-1-programming-steps" aria-label="Permalink to &quot;2.3.1 Programming Steps&quot;">​</a></h3><ol><li><strong>Open the software</strong>: Start the programming software and create a new project.</li></ol><img loading="lazy" height="879" width="1590" src="'+_+'" class="inline-icon" style="width:700px;"><ol start="2"><li><strong>Add the extension</strong></li></ol><ul><li>Open the <strong>Choose an Extension</strong> interface by clicking the icon in the lower-left corner of the software.</li></ul><img loading="lazy" height="1040" width="1920" src="'+o+'" class="inline-icon" style="width:700px;"><ul><li>In <strong>Choose an Extension</strong>, choose <strong>Controller</strong> and add <strong>K12 ESP32</strong>.</li></ul><img loading="lazy" height="879" width="1590" src="'+k+'" class="inline-icon" style="width:700px;"><ul><li>After the extension is added successfully, the added package appears in the WonderCode interface.</li></ul><img loading="lazy" height="879" width="1590" src="'+f+'" class="inline-icon" style="width:700px;"><ol start="3"><li><strong>Write the program</strong>: Drag the required blocks from the command area into the script area to create the program. After the program is completed, the converted Python code appears in the code display and upload area.</li></ol><img loading="lazy" height="326" width="351" src="'+y+'" class="inline-icon" style="width:500px;"><h3 id="_2-3-2-program-download-steps" tabindex="-1">2.3.2 Program Download Steps <a class="header-anchor" href="#_2-3-2-program-download-steps" aria-label="Permalink to &quot;2.3.2 Program Download Steps&quot;">​</a></h3><ol><li>Set the controller power switch to <strong>ON</strong>, then connect a USB data cable to the program download port on the controller.</li></ol><img loading="lazy" height="1460" width="1460" src="'+D+'" class="inline-icon" style="width:400px;"><ol start="2"><li>Plug the other end of the cable into a USB port on the computer.</li></ol><img loading="lazy" height="432" width="357" src="'+x+'" class="inline-icon" style="width:200px;"><ol start="3"><li>Click <strong>Connect</strong> and select the corresponding port.</li></ol><img loading="lazy" height="144" width="441" src="'+P+'" class="inline-icon" style="width:400px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>The port number is not fixed. The example in this section uses COM3, but COM1 should not be selected because it is usually reserved for system communication. If multiple COM ports are shown and the correct one is unclear, right-click This PC, select Properties &gt; Device Manager, and check the port assigned to the controller. The correct port typically includes the CH340 identifier.</strong></p></div><img loading="lazy" height="129" width="240" src="'+C+'" class="inline-icon" style="width:350px;"><h3 id="_2-3-3-downloading-the-program" tabindex="-1">2.3.3 Downloading the Program <a class="header-anchor" href="#_2-3-3-downloading-the-program" aria-label="Permalink to &quot;2.3.3 Downloading the Program&quot;">​</a></h3><ol><li><p>Click <strong>Connect</strong> and select the corresponding port.</p></li><li><p>Click the <strong>Download</strong> button in the upper-right corner to download the program to the controller.</p></li></ol><img loading="lazy" height="892" width="1384" src="'+r+'" class="inline-icon" style="width:700px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>If no COM port appears after the controller is connected, check whether the USB cable is a data cable, or try another USB data port on the computer.</strong></p></div><h2 id="_2-4-starter-project-2-multi-electronic-module-control" tabindex="-1">2.4 Starter Project 2: Multi-Electronic Module Control <a class="header-anchor" href="#_2-4-starter-project-2-multi-electronic-module-control" aria-label="Permalink to &quot;2.4 Starter Project 2: Multi-Electronic Module Control&quot;">​</a></h2><h3 id="_2-4-1-learning-objectives" tabindex="-1">2.4.1 Learning Objectives <a class="header-anchor" href="#_2-4-1-learning-objectives" aria-label="Permalink to &quot;2.4.1 Learning Objectives&quot;">​</a></h3><ol><li>Understand the touch sensor, button module, sound sensor, 360° block servo, and glowy ultrasonic sensor module, and master the basic wiring and initialization operations of each module.</li><li>Master the programming logic of using buttons to control the start and stop of the 360° block servo via the ESP32 controller, and understand using conditional statements to control servo rotation speed.</li><li>Master the sound sensor volume threshold judgment programming to trigger the glowy ultrasonic sensor RGB lights to display a fixed single color when the volume exceeds the threshold.</li><li>Master the control logic of the touch sensor triggering the glowy ultrasonic sensor RGB lights into dazzling color mode, and understand the execution order of multi-layer nested conditional programs.</li></ol><h3 id="_2-4-2-wiring-diagram" tabindex="-1">2.4.2 Wiring Diagram <a class="header-anchor" href="#_2-4-2-wiring-diagram" aria-label="Permalink to &quot;2.4.2 Wiring Diagram&quot;">​</a></h3><p>Connect the glowy ultrasonic sensor cable to port P1 of the ESP32 controller;</p><p>Connect the touch sensor cable to port P5 of the ESP32 controller;</p><p>Connect the button module cable to port P6 of the ESP32 controller;</p><p>Connect the sound sensor module cable to port P7 of the ESP32 controller;</p><p>Connect the 360° continuous rotation block servo cable to port S1 of the ESP32 controller, inserting the orange signal wire of the servo into the white signal pin of S1.</p><p>As shown in the diagram:</p><img loading="lazy" height="495" width="642" src="'+S+'" class="common_img" style="width:500px;"><h3 id="_2-4-3-programming" tabindex="-1">2.4.3 Programming <a class="header-anchor" href="#_2-4-3-programming" aria-label="Permalink to &quot;2.4.3 Programming&quot;">​</a></h3><h4 id="_1-add-extension-libraries" tabindex="-1">(1) Add Extension Libraries <a class="header-anchor" href="#_1-add-extension-libraries" aria-label="Permalink to &quot;(1) Add Extension Libraries&quot;">​</a></h4><p>Select <strong>Sensor</strong> in the <strong>Choose an Extension</strong> interface to add <strong>Glowy ultrasonic sensor</strong>, <strong>Touch sensor</strong>, <strong>Sound sensor</strong>, and <strong>Button module</strong>.</p><img loading="lazy" height="1040" width="1920" src="'+o+'" class="common_img" style="width:800px;"><h4 id="_2-complete-program" tabindex="-1">(2) Complete Program <a class="header-anchor" href="#_2-complete-program" aria-label="Permalink to &quot;(2) Complete Program&quot;">​</a></h4><img loading="lazy" height="677" width="471" src="'+q+'" class="common_img" style="width:500px;"><h3 id="_2-4-4-downloading-the-program" tabindex="-1">2.4.4 Downloading the Program <a class="header-anchor" href="#_2-4-4-downloading-the-program" aria-label="Permalink to &quot;2.4.4 Downloading the Program&quot;">​</a></h3><ol><li><p>Click <strong>Connect</strong> and select the corresponding port.</p></li><li><p>Click the <strong>Download</strong> button in the upper-right corner to download the program to the controller.</p></li></ol><img loading="lazy" height="892" width="1384" src="'+r+'" class="common_img" style="width:600px;"><h3 id="_2-4-5-program-outcome" tabindex="-1">2.4.5 Program Outcome <a class="header-anchor" href="#_2-4-5-program-outcome" aria-label="Permalink to &quot;2.4.5 Program Outcome&quot;">​</a></h3><p>Once the program starts running, initialize the glowy ultrasonic sensor port and touch sensor port. Then, execute the loop: when detecting that the button module at port 6 is pressed, the 360° block servo at port S1 rotates at a speed of 50 and stops when released. Detect the volume of the sound sensor at port 7: when the volume is greater than 70, all RGB lights of the glowy ultrasonic sensor light up red. When the volume is less than or equal to 70, pressing the touch sensor switches the RGB lights of the glowy ultrasonic sensor to dazzling color mode, with a 0.1-second interval for each loop.</p>',78)])])}const W=i(v,[["render",j]]);export{M as __pageData,W as default};
